package dev.srpbackport.tests;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.lang.reflect.Modifier;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import net.minecraft.world.*;import net.minecraft.entity.*;import net.minecraft.entity.monster.EntityZombie;import net.minecraft.entity.passive.EntityPig;import net.minecraft.entity.ai.EntityMoveHelper;import net.minecraft.server.MinecraftServer;
import com.dhanantry.scapeandrunparasites.backport.entity.EntityQueries;
@Mod(modid="srp_entity_common_checks",name="Disposable entity common checks",version="1")
public final class NativeEntityCommonChecks{
 static final List<String> report=new ArrayList<String>();int ticks,failed;boolean done;
 public static class Move extends EntityMoveHelper{Move(EntityLiving living){super(living);}void change(){this.posX=24;this.posY=80;this.posZ=20;this.speed=1.3;}}
 @Mod.EventHandler public void init(FMLInitializationEvent e){if(e.getSide().isClient())try{Class.forName("dev.srpbackport.tests.NativeEntityCommonClientChecks").getMethod("initialize").invoke(null);}catch(Exception problem){throw new RuntimeException(problem);}else FMLCommonHandler.instance().bus().register(this);}
 interface Check{void run()throws Exception;}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}void test(String name,Check c){try{c.run();report.add("PASS: "+name);}catch(Throwable problem){failed++;report.add("FAIL: "+name+" :: "+problem);problem.printStackTrace();}}
 void tests(WorldServer world){
  test("Real Forge loads the mod manifest access rules before entity classes",()->{check(Modifier.isPublic(cpw.mods.fml.relauncher.ReflectionHelper.findField(EntityLiving.class,"moveHelper","field_70765_h").getModifiers()),"Native moveHelper remains private");for(String[] names:new String[][]{{"posX","field_75646_b"},{"posY","field_75647_c"},{"posZ","field_75644_d"},{"speed","field_75645_e"}})check(Modifier.isPublic(cpw.mods.fml.relauncher.ReflectionHelper.findField(EntityMoveHelper.class,names).getModifiers()),"Native move member remains private: "+names[0]);});
  test("Native movement uses a replaced helper and its original coordinate/speed fields",()->{EntityZombie actor=new EntityZombie(world);actor.setPosition(20,80,20);Move helper=new Move(actor);actor.moveHelper=helper;check(actor.getMoveHelper()==helper,"Replacement helper not visible to native engine");helper.setMoveTo(21,81,22,0.75);check(helper.posX==21&&helper.posY==81&&helper.posZ==22&&helper.speed==0.75,"Native setter fields diverged");helper.change();check(helper.getSpeed()==1.3,"Native getter did not observe changed field");helper.onUpdateMoveHelper();check(actor.getAIMoveSpeed()>0,"Native move update did not drive actor");});
  test("Converted typed queries, predicates, position calls and live-list iteration execute on a real world",()->{EntityZombie actor=new EntityZombie(world);actor.setPosition(20,80.1,20);EntityPig pig=new EntityPig(world);pig.setPosition(21,80,21);check(world.spawnEntityInWorld(actor)&&world.spawnEntityInWorld(pig),"Fixture spawn");EntityQueryFixture.run(world,actor);});
  test("Typed loaded/player collections retain the native list identity and null predicates retain native query results",()->{check((Object)EntityQueries.loaded(world)==world.loadedEntityList&&(Object)EntityQueries.players(world)==world.playerEntities,"Live list identity changed");net.minecraft.util.AxisAlignedBB box=net.minecraft.util.AxisAlignedBB.getBoundingBox(16,75,16,28,90,28);check(EntityQueries.entities(world,EntityZombie.class,box,null).size()==world.getEntitiesWithinAABB(EntityZombie.class,box).size(),"Null predicate differs");});
 }
 @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||++ticks!=20)return;try{WorldServer w=MinecraftServer.getServer().worldServerForDimension(0);w.getChunkFromChunkCoords(1,1);tests(w);}catch(Throwable problem){failed++;report.add("FAIL: setup :: "+problem);problem.printStackTrace();}finally{done=true;report.add("Failed: "+failed);try{Files.write(Paths.get("entity-common-initial.txt"),report,StandardCharsets.UTF_8);}catch(IOException problem){throw new RuntimeException(problem);}MinecraftServer.getServer().initiateShutdown();}}
}
